:root { color-scheme: dark; font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: rgb(241, 244, 239); background: rgb(9, 11, 10); font-synthesis: none; --signal: #aaff1e; --signal-soft: rgba(170, 255, 30, .14); --ink: #f1f4ef; --muted: #89928b; --line: rgba(232, 242, 234, .13); --surface: #101311; --surface-raised: #161a17; }* { box-sizing: border-box; }html, body, #app { width: 100%; min-width: 320px; min-height: 100%; margin: 0px; }body { overflow-x: hidden; background: rgb(9, 11, 10); }button, input, textarea { font: inherit; }button { color: inherit; }.app-shell { min-height: 100svh; display: grid; grid-template-rows: 66px 88px minmax(520px, 1fr) 160px; background: radial-gradient(circle at 38% 45%, rgba(170, 255, 30, 0.043), transparent 34%), rgb(9, 11, 10); }.trust-switch { display: grid; grid-template-columns: minmax(190px, 0.65fr) minmax(480px, 1.55fr) auto; align-items: stretch; border-bottom: 1px solid var(--line); background: rgb(11, 14, 12); position: relative; z-index: 4; }.trust-switch__copy { display: flex; flex-direction: column; justify-content: center; gap: 7px; padding: 0px 22px; border-right: 1px solid var(--line); }.trust-switch__copy small, .trust-switch__copy strong, .trust-switch > a, .trust-mode { font-family: SFMono-Regular, Consolas, monospace; }.trust-switch__copy small { color: var(--muted); font-size: 7px; letter-spacing: 0.16em; }.trust-switch__copy strong { color: var(--signal); font-size: 9px; letter-spacing: 0.09em; }.trust-switch__modes { display: grid; grid-template-columns: repeat(3, 1fr); }.trust-mode { display: grid; grid-template-columns: 28px 1fr; grid-template-rows: 1fr 1fr; align-items: end; padding: 13px 18px; border-top: 0px; border-bottom: 0px; border-left: 0px; border-image: none; border-right: 1px solid var(--line); color: var(--muted); background: transparent; text-align: left; cursor: pointer; transition: background 0.2s, color 0.2s; }.trust-mode > span { grid-row: 1 / 3; align-self: center; color: rgb(94, 103, 95); font-size: 9px; }.trust-mode strong { align-self: end; color: rgb(200, 207, 201); font-size: 10px; letter-spacing: 0.1em; }.trust-mode small { align-self: start; margin-top: 3px; font-size: 8px; }.trust-mode--active { color: var(--signal); background: linear-gradient(90deg,var(--signal-soft),transparent); box-shadow: inset 0 -2px var(--signal); }.trust-mode--active strong, .trust-mode--active > span { color: var(--signal); }.trust-switch > a { display: flex; align-items: center; padding: 0px 20px; color: rgb(166, 174, 167); text-decoration: none; font-size: 8px; letter-spacing: 0.1em; white-space: nowrap; }.trust-switch > a:hover { color: var(--signal); }.topbar { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; border-bottom: 1px solid var(--line); background: rgba(9, 11, 10, 0.92); padding: 0px 22px; position: relative; z-index: 5; }.brand, .event-title, .system-state { display: flex; align-items: center; }.brand { gap: 13px; font-size: 11px; font-weight: 720; letter-spacing: 0.14em; }.brand__mark { display: grid; place-items: center; width: 35px; height: 35px; color: rgb(9, 11, 10); background: var(--signal); font-size: 15px; font-weight: 900; letter-spacing: -0.05em; clip-path: polygon(0px 0px, 100% 0px, 100% 76%, 76% 100%, 0px 100%); }.event-title { flex-direction: column; gap: 2px; text-align: center; }.event-title span, .system-state small { font-size: 8px; letter-spacing: 0.18em; color: var(--muted); }.event-title strong { font-family: SFMono-Regular, Consolas, monospace; font-size: 11px; letter-spacing: 0.11em; }.system-state { justify-content: flex-end; gap: 8px; font-family: SFMono-Regular, Consolas, monospace; font-size: 9px; letter-spacing: 0.12em; }.system-state small { margin-left: 10px; }.status-dot { width: 6px; height: 6px; border-radius: 50%; background: rgb(123, 132, 125); box-shadow: rgba(123, 132, 125, 0.1) 0px 0px 0px 4px; }.status-dot--ready, .status-dot--running { background: var(--signal); box-shadow: 0 0 12px var(--signal); }.status-dot--countdown { background: rgb(255, 204, 54); box-shadow: rgb(255, 204, 54) 0px 0px 12px; }.status-dot--fallen, .status-dot--error { background: rgb(255, 81, 71); box-shadow: rgb(255, 81, 71) 0px 0px 12px; }.workspace { min-height: 0px; display: grid; grid-template-columns: minmax(0px, 1fr) 338px; }.simulation { min-height: 0px; position: relative; overflow: hidden; border-right: 1px solid var(--line); }.viewport, .viewport canvas { width: 100%; height: 100%; display: block; }.viewport { min-height: 520px; }.viewport::after { content: ""; position: absolute; inset: 0px; pointer-events: none; background: linear-gradient(rgba(9, 11, 10, 0.5), transparent 22%, transparent 74%, rgba(9, 11, 10, 0.64)); }.viewport__hud { position: absolute; z-index: 2; left: 22px; right: 22px; pointer-events: none; }.viewport__hud--top { top: 18px; display: flex; justify-content: space-between; align-items: flex-start; }.viewport__hud--top > div:first-child { display: flex; flex-direction: column; gap: 5px; }.viewport__hud small, .model-tags span, .field-position, .field-bearing { font-family: SFMono-Regular, Consolas, monospace; }.viewport__hud small { color: var(--signal); font-size: 8px; letter-spacing: 0.18em; }.viewport__hud strong { font-size: 15px; letter-spacing: 0.1em; }.model-tags { display: flex; gap: 6px; }.model-tags span { border: 1px solid var(--line); padding: 6px 8px; font-size: 8px; color: rgb(195, 203, 196); background: rgba(9, 11, 10, 0.5); }.viewport__hud--bottom { bottom: 19px; }.field-position { display: flex; gap: 18px; color: rgb(137, 146, 139); font-size: 8px; letter-spacing: 0.09em; }.field-position b { color: var(--ink); font-weight: 500; }.field-position span:last-child { margin-left: auto; color: var(--signal); }.isolated-only, .agent-only { display: none; }.app-shell--isolated .isolated-only, .app-shell--agent .agent-only { display: inline; }.app-shell--isolated .preview-only, .app-shell--isolated .drive-pad, .app-shell--agent .preview-only, .app-shell--agent .drive-pad { display: none; }.field-bearing { display: flex; align-items: center; gap: 10px; margin-top: 9px; color: rgb(98, 108, 100); font-size: 7px; letter-spacing: 0.13em; }.field-bearing i { display: block; flex: 1 1 0%; height: 1px; background: linear-gradient(90deg,var(--signal),rgba(170,255,30,.06)); }.toolrail { position: absolute; z-index: 3; left: 20px; top: 50%; transform: translateY(-50%); display: flex; flex-direction: column; gap: 7px; }.toolrail > span { height: 1px; width: 28px; background: var(--line); margin: 2px 0px; }.tool-button { width: 28px; height: 28px; border: 1px solid var(--line); background: rgba(9, 11, 10, 0.62); font: 700 9px / 1 SFMono-Regular, Consolas, monospace; color: var(--muted); cursor: pointer; transition: 0.16s; }.tool-button:hover, .tool-button--active { color: rgb(9, 11, 10); border-color: var(--signal); background: var(--signal); transform: translate(2px); }.drive-pad { position: absolute; z-index: 3; right: 24px; bottom: 62px; display: grid; grid-template-columns: repeat(3, 34px); grid-template-rows: repeat(2, 34px); gap: 5px; }.drive-pad button { border: 1px solid var(--line); background: rgba(9, 11, 10, 0.7); color: rgb(155, 164, 157); font: 800 10px SFMono-Regular, Consolas, monospace; cursor: pointer; backdrop-filter: blur(7px); transition: 0.12s; touch-action: none; }.drive-pad button:first-child { grid-column: 2; }.drive-pad button:nth-child(2) { grid-area: 2 / 1; }.drive-pad button:nth-child(3) { grid-area: 2 / 2; }.drive-pad button:nth-child(4) { grid-area: 2 / 3; }.drive-pad button:hover, .drive-pad .drive-key--active { color: rgb(9, 11, 10); background: var(--signal); border-color: var(--signal); transform: translateY(-1px); }.countdown { position: absolute; inset: 0px; z-index: 4; display: grid; place-items: center; font-size: clamp(92px, 15vw, 220px); font-weight: 900; color: var(--signal); letter-spacing: -0.08em; opacity: 0; pointer-events: none; transform: scale(0.82); text-shadow: rgba(170, 255, 30, 0.24) 0px 0px 60px; transition: opacity 0.14s, transform 0.2s cubic-bezier(0.2, 0.8, 0.2, 1); }.countdown--visible { opacity: 0.92; transform: scale(1); }.result { position: absolute; z-index: 4; inset: 0px; display: flex; flex-direction: column; justify-content: center; align-items: center; background: rgba(6, 8, 7, 0.76); backdrop-filter: blur(10px); opacity: 0; pointer-events: none; transition: opacity 0.25s; }.result--visible { opacity: 1; pointer-events: auto; }.result small { color: var(--signal); letter-spacing: 0.22em; font-size: 9px; }.result strong { font: 800 clamp(70px, 10vw, 132px) / 0.92 SFMono-Regular, Consolas, monospace; letter-spacing: -0.08em; }.result span { margin-top: 8px; font: 9px SFMono-Regular, Consolas, monospace; letter-spacing: 0.24em; color: var(--muted); }.result p { font: 11px SFMono-Regular, Consolas, monospace; color: rgb(198, 206, 199); }.inspector { min-height: 0px; background: rgb(14, 17, 15); display: flex; flex-direction: column; }.panel-tabs { display: grid; grid-template-columns: repeat(4, 1fr); height: 44px; border-bottom: 1px solid var(--line); }.panel-tab { position: relative; border: 0px; background: transparent; color: var(--muted); font-size: 9px; font-weight: 760; letter-spacing: 0.16em; cursor: pointer; }.panel-tab::after { content: ""; position: absolute; left: 20px; right: 20px; bottom: -1px; height: 2px; background: transparent; }.panel-tab--active { color: var(--ink); }.panel-tab--active::after { background: var(--signal); }.inspector-panel { display: none; min-height: 0px; }.inspector-panel--active { display: block; animation: 0.3s ease 0s 1 normal both running panel-in; }.inspector-panel--code.inspector-panel--active { display: grid; grid-template-rows: 39px minmax(230px, 1fr) auto auto auto auto; height: calc(100% - 44px); }@keyframes panel-in { 
