}.mode-note { padding: 22px; border-bottom: 1px solid var(--line); }.mode-note span, .section-label span, .sensor-readout span, .editor-head, .console, .button, .range-label { font-family: SFMono-Regular, Consolas, monospace; }.mode-note span { display: inline-block; color: var(--signal); font-size: 8px; letter-spacing: 0.18em; margin-bottom: 8px; }.mode-note p { margin: 0px; max-width: 28ch; color: rgb(162, 170, 163); font-size: 11px; line-height: 1.55; }.inspector-panel--agent { height: calc(100% - 44px); overflow: auto; }.agent-grid { display: grid; grid-template-columns: 1fr 1fr; margin: 0px; }.agent-grid > div { min-width: 0px; padding: 11px 14px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); }.agent-grid > div:nth-child(2n) { border-right: 0px; }.agent-grid dt { color: var(--muted); font: 7px SFMono-Regular, Consolas, monospace; letter-spacing: 0.13em; }.agent-grid dd { margin: 6px 0px 0px; overflow: hidden; text-overflow: ellipsis; color: var(--ink); font: 12px SFMono-Regular, Consolas, monospace; white-space: nowrap; }.agent-actions { display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px; padding: 12px; border-bottom: 1px solid var(--line); }.agent-actions button { min-height: 34px; border: 1px solid var(--line); background: rgb(10, 13, 11); color: rgb(185, 193, 186); font: 8px SFMono-Regular, Consolas, monospace; letter-spacing: 0.08em; cursor: pointer; transition: 0.14s; }.agent-actions button:hover { color: rgb(9, 11, 10); background: var(--signal); border-color: var(--signal); }.agent-actions button:nth-child(4), .agent-actions button:nth-child(5) { grid-column: span 1; }.agent-command-form { display: grid; grid-template-columns: 0.7fr 0.7fr 0.8fr 1.4fr; gap: 7px; padding: 10px 12px; border-bottom: 1px solid var(--line); background: rgb(13, 16, 14); }.agent-command-form label { display: grid; gap: 4px; color: var(--muted); font: 7px / 1 SFMono-Regular, Consolas, monospace; letter-spacing: 0.12em; }.agent-command-form input { width: 100%; min-width: 0px; border: 1px solid var(--line-strong); background: rgb(8, 10, 9); color: var(--text); padding: 8px 7px; font: 10px SFMono-Regular, Consolas, monospace; }.agent-command-form button { align-self: end; border: 1px solid var(--acid); background: transparent; color: var(--acid); padding: 8px 6px; font: 700 8px SFMono-Regular, Consolas, monospace; letter-spacing: 0.08em; }.agent-command-form button:disabled { opacity: 0.45; }.agent-transcript { min-height: 86px; max-height: 112px; margin: 0px; overflow: auto; padding: 12px 14px; border-bottom: 1px solid var(--line); background: rgb(9, 11, 10); color: rgb(137, 146, 139); font: 8px / 1.55 SFMono-Regular, Consolas, monospace; }.agent-transcript-json { position: fixed; left: -10000px; width: 1px; height: 1px; opacity: 0; pointer-events: none; }.agent-interface { padding: 9px 14px 0px; color: var(--acid); font: 8px / 1.3 SFMono-Regular, Consolas, monospace; letter-spacing: 0.1em; }.agent-footer { display: grid; grid-template-columns: 0.8fr 0.9fr 1.35fr; gap: 8px; padding: 10px; }.control-section { padding: 19px 22px; border-bottom: 1px solid var(--line); }.section-label { display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; }.section-label span { font-size: 8px; letter-spacing: 0.15em; color: rgb(198, 206, 199); }.section-label output { color: var(--signal); font: 10px SFMono-Regular, Consolas, monospace; }input[type="range"] { width: 100%; height: 2px; margin: 0px; appearance: none; background: linear-gradient(90deg,var(--signal),#424943); outline: none; }input[type="range"]::-webkit-slider-thumb { appearance: none; width: 12px; height: 12px; border: 3px solid rgb(14, 17, 15); border-radius: 50%; background: var(--signal); box-shadow: 0 0 0 1px var(--signal); cursor: pointer; }.range-label { display: flex; justify-content: space-between; margin-top: 8px; color: rgb(99, 107, 101); font-size: 7px; letter-spacing: 0.1em; }.segment { display: grid; grid-template-columns: repeat(3, 1fr); border: 1px solid var(--line); }.segment button { height: 31px; border-top: 0px; border-bottom: 0px; border-left: 0px; border-image: none; border-right: 1px solid var(--line); background: transparent; color: var(--muted); font: 9px SFMono-Regular, Consolas, monospace; cursor: pointer; }.segment button:last-child { border-right: 0px; }.segment .segment__button--active { background: var(--signal-soft); color: var(--signal); }.sensor-readout { display: grid; grid-template-columns: 1fr 1fr; padding: 19px 22px; gap: 18px; }.sensor-readout > div { display: flex; flex-direction: column; gap: 5px; }.sensor-readout span { font-size: 7px; letter-spacing: 0.13em; color: var(--muted); }.sensor-readout strong { font: 500 15px SFMono-Regular, Consolas, monospace; }.sensor-readout .drive { grid-column: 1 / -1; }.drive i { position: relative; height: 4px; background: rgb(37, 43, 39); margin-top: 2px; overflow: hidden; }.drive i::after { content: ""; display: block; width: var(--drive, 0%); height: 100%; background: var(--signal); transition: width 0.1s linear; }.editor-head { display: flex; align-items: center; justify-content: space-between; padding: 0px 14px; border-bottom: 1px solid var(--line); color: rgb(199, 206, 200); font-size: 9px; }.editor-head small { color: var(--signal); font-size: 7px; letter-spacing: 0.14em; }.code-editor { resize: none; width: 100%; min-height: 0px; border: 0px; outline: none; padding: 15px 14px 40px; background: rgb(11, 14, 12); color: rgb(200, 208, 201); font: 11px / 1.6 SFMono-Regular, Consolas, monospace; tab-size: 2; }.code-editor:focus { box-shadow: inset 2px 0 var(--signal); }.console { min-height: 42px; max-height: 74px; overflow: auto; padding: 9px 14px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); color: rgb(134, 144, 135); font-size: 8px; line-height: 1.45; }.console--error { color: rgb(255, 117, 109); }.editor-actions { display: grid; grid-template-columns: 1fr 1.4fr; gap: 8px; padding: 10px; }.editor-actions:has(#isolated-button) { grid-template-columns: 0.7fr 1fr 1.5fr; }.evaluation-input { display: grid; grid-template-columns: auto 90px 1fr; align-items: center; gap: 9px; padding: 9px 14px; border-top: 1px solid var(--line); font: 8px SFMono-Regular, Consolas, monospace; color: var(--muted); }.evaluation-input input { min-width: 0px; height: 28px; border: 1px solid var(--line); background: rgb(9, 11, 10); color: var(--ink); padding: 0px 8px; outline: none; font: 10px SFMono-Regular, Consolas, monospace; }.evaluation-input input:focus { border-color: var(--signal); }.evaluation-input span { text-align: right; color: rgb(101, 112, 103); }.evaluation-status { min-height: 36px; max-height: 58px; }.button:disabled { opacity: 0.45; cursor: wait; transform: none; }.inspector-panel--evidence { height: calc(100% - 44px); overflow: auto; }.evidence-intro { padding: 18px 20px; border-bottom: 1px solid var(--line); }.evidence-intro span { color: var(--signal); font: 8px SFMono-Regular, Consolas, monospace; letter-spacing: 0.16em; }.evidence-intro p { margin: 7px 0px 0px; color: rgb(164, 173, 165); font-size: 10px; line-height: 1.5; }.evidence-grid { display: grid; grid-template-columns: 1fr 1fr; margin: 0px; }.evidence-grid > div { min-width: 0px; padding: 12px 15px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); }.evidence-grid > div:nth-child(2n) { border-right: 0px; }.evidence-grid dt, .hash-stack span, .replay-control span, .replay-control small { color: var(--muted); font: 7px SFMono-Regular, Consolas, monospace; letter-spacing: 0.13em; }.evidence-grid dd { margin: 6px 0px 0px; overflow: hidden; text-overflow: ellipsis; color: var(--ink); font: 13px SFMono-Regular, Consolas, monospace; }.hash-stack { display: grid; gap: 6px; padding: 14px 15px; border-bottom: 1px solid var(--line); }.hash-stack code { display: block; overflow: hidden; text-overflow: ellipsis; color: rgb(201, 209, 202); font: 8px SFMono-Regular, Consolas, monospace; white-space: nowrap; }.hash-stack code + span { margin-top: 5px; }.replay-control { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; padding: 14px; }.replay-control > div { grid-column: 1 / -1; display: flex; justify-content: space-between; }.replay-control > div span { color: var(--signal); }.replay-control input { grid-column: 1 / -1; }.app-shell--isolated .run-controls #power-button, .app-shell--isolated .run-controls #reset-button, .app-shell--isolated .run-controls #run-button, .app-shell--agent .run-controls #power-button, .app-shell--agent .run-controls #reset-button, .app-shell--agent .run-controls #run-button { opacity: 0.28; pointer-events: none; }.telemetry { min-width: 0px; display: grid; grid-template-columns: minmax(360px, 1.1fr) minmax(190px, 0.7fr) minmax(190px, 0.7fr) auto; align-items: stretch; border-top: 1px solid var(--line); background: rgb(12, 15, 13); }.metrics { display: grid; grid-template-columns: repeat(4, 1fr); }.metrics > div { display: flex; flex-direction: column; justify-content: center; padding: 18px; border-right: 1px solid var(--line); }.metrics span, .chart__label { font: 7px SFMono-Regular, Consolas, monospace; color: var(--muted); letter-spacing: 0.12em; }.metrics strong { margin-top: 10px; font: 400 clamp(18px, 2vw, 29px) SFMono-Regular, Consolas, monospace; letter-spacing: -0.06em; }.chart { min-width: 0px; padding: 17px 14px 10px; border-right: 1px solid var(--line); }.chart__label { display: flex; justify-content: space-between; }.chart__label small { color: var(--signal); font-size: 7px; }.chart svg { width: 100%; height: 91px; overflow: visible; margin-top: 8px; }.chart path { stroke: rgba(255, 255, 255, 0.07); stroke-width: 0.7; fill: none; }.chart polyline { stroke: var(--signal); stroke-width: 1.5; fill: none; vector-effect: non-scaling-stroke; filter: drop-shadow(rgba(170, 255, 30, 0.4) 0px 0px 3px); }.chart:last-of-type polyline { stroke: rgb(241, 244, 239); filter: none; }.run-controls { display: grid; grid-template-columns: 88px 74px 120px; gap: 8px; align-content: center; padding: 18px; }.button { height: 40px; border: 1px solid var(--line); background: transparent; font-size: 8px; font-weight: 750; letter-spacing: 0.12em; cursor: pointer; transition: 0.16s; }.button:hover { border-color: rgb(230, 238, 231); transform: translateY(-1px); }.button--accent { color: rgb(9, 11, 10); background: var(--signal); border-color: var(--signal); box-shadow: rgba(170, 255, 30, 0.08) 0px 0px 20px; }.button--accent:hover { box-shadow: rgba(170, 255, 30, 0.2) 0px 0px 24px; }.button--power { color: var(--signal); border-color: rgba(170, 255, 30, 0.3); }.button--power.power--off { color: rgb(255, 102, 93); border-color: rgba(255, 102, 93, 0.34); }.boot { position: fixed; z-index: 20; inset: 0px; display: flex; flex-direction: column; align-items: center; justify-content: center; background: rgb(9, 11, 10); opacity: 1; visibility: visible; transition: opacity 0.45s, visibility 0.45s; }.boot--hidden { opacity: 0; visibility: hidden; pointer-events: none; }.boot__brand { display: grid; place-items: center; width: 78px; height: 78px; margin-bottom: 25px; background: var(--signal); color: rgb(9, 11, 10); font-size: 29px; font-weight: 950; letter-spacing: -0.08em; clip-path: polygon(0px 0px, 100% 0px, 100% 76%, 76% 100%, 0px 100%); animation: 0.7s cubic-bezier(0.2, 0.8, 0.2, 1) 0s 1 normal both running boot-mark; }@keyframes boot-mark { 
  0% { opacity: 0; transform: scale(0.7) rotate(-8deg); }
}.boot p { margin: 0px 0px 15px; font: 9px SFMono-Regular, Consolas, monospace; text-transform: uppercase; letter-spacing: 0.16em; color: rgb(180, 188, 181); }.boot small { margin-top: 15px; font: 7px SFMono-Regular, Consolas, monospace; letter-spacing: 0.16em; color: rgb(94, 102, 95); }.boot__track { width: 260px; height: 2px; background: rgb(38, 43, 39); overflow: hidden; }.boot__track i { display: block; width: var(--progress, 0%); height: 100%; background: var(--signal); box-shadow: 0 0 10px var(--signal); transition: width 0.35s; }.boot--error .boot__brand, .boot--error .boot__track i { background: rgb(255, 81, 71); }.boot--error p { max-width: 48ch; color: rgb(255, 117, 109); text-align: center; line-height: 1.6; }@media (max-width: 1080px) {
  .app-shell { grid-template-rows: 62px auto minmax(540px, auto) auto; }
